// Verify Lightspeed webhook signature header is present
// Full HMAC-SHA256 verification requires crypto module (sandboxed in n8n)
// Security: unique webhook URL path + signature presence check
const headers = $input.first().json.headers || {};
const body = $input.first().json.body;

const signature = headers['x-signature'] || headers['X-Signature'];
if (!signature) {
  throw new Error('Missing x-signature header — webhook rejected');
}

const payload = typeof body === 'string' ? JSON.parse(body) : body;

// LS X-Series webhook format: { domain_prefix, type, payload: { ...sale... } }
if (!payload || !payload.payload) {
  throw new Error('Invalid webhook payload structure — expected payload.payload');
}

return [{ json: { verified: true, payload: payload.payload } }];

// Extract sale data from webhook payload + customer data from LS API
const sale = $('Verify HMAC Signature').first().json.payload;
const fetchResult = $json;
const customerData = fetchResult.data || fetchResult;

// Customer details: prefer LS API response, fall back to sale payload
const customerEmail = customerData.email || sale.customer_email || (sale.customer && sale.customer.email) || '';
const customerFirstName = customerData.first_name || sale.customer_first_name || (sale.customer && sale.customer.first_name) || '';
const customerLastName = customerData.last_name || sale.customer_last_name || (sale.customer && sale.customer.last_name) || '';
const customerPhone = customerData.phone || customerData.mobile || sale.customer_phone || (sale.customer && sale.customer.phone) || '';

const saleId = sale.id || sale.sale_id;
const saleTotal = parseFloat(sale.total_price_incl || sale.total_inc_tax || sale.total || 0);
const employeeId = sale.user_id || sale.employee_id || '';
const registerId = sale.register_id || '';
const saleDate = sale.sale_date || sale.completed_at || new Date().toISOString().split('T')[0];

// Category → tag mapping
// LS X-Series webhook register_sale_products include 'name' (product name)
// We match on product name keywords since product_type_name isn't in the webhook payload
const nameTagRules = [
  { pattern: /tattoo/i, tag: '[client] tattoo' },
  { pattern: /microbla/i, tag: '[client] tattoo' },
  { pattern: /pierc/i, tag: '[client] piercing' },
  { pattern: /tooth\s*gem/i, tag: '[client] piercing' }
];

// Also check product_type_name if available (e.g., from enriched payloads)
const categoryTagMap = {
  'tattoo artist': '[client] tattoo',
  'microblader': '[client] tattoo',
  'piercing': '[client] piercing',
  'piercer': '[client] piercing',
  'tooth gem': '[client] piercing'
};

const tags = new Set(['[system] lightspeed-customer']);
const lineItems = sale.register_sale_products || sale.line_items || [];

for (const item of lineItems) {
  const productName = (item.name || '').toLowerCase().trim();
  const typeName = (item.product_type_name || item.category_name || item.type || '').toLowerCase().trim();

  // Check product_type_name first (if available)
  for (const [key, tag] of Object.entries(categoryTagMap)) {
    if (typeName.includes(key)) {
      tags.add(tag);
    }
  }

  // Then check product name keywords
  for (const rule of nameTagRules) {
    if (rule.pattern.test(productName)) {
      tags.add(rule.tag);
    }
  }
}

if (!customerEmail) {
  throw new Error(`Sale ${saleId}: customer ${sale.customer_id} has no email in Lightspeed — cannot sync to GHL`);
}

return [{
  json: {
    customerEmail,
    customerFirstName,
    customerLastName,
    customerPhone,
    saleId: String(saleId),
    saleTotal,
    saleDate,
    employeeId: String(employeeId),
    registerId: String(registerId),
    tags: Array.from(tags),
    hasTattoo: tags.has('[client] tattoo'),
    hasPiercing: tags.has('[client] piercing')
  }
}];

// Calculate updated lifetime value and prepare custom field update
const contact = $json.contact || {};
const saleData = $('Extract Sale Data + Tags').first().json;
const matcherData = $('Find/Create Customer').first().json;

// Get existing lifetime value from custom fields
let existingLifetime = 0;
const customFields = contact.customFields || contact.customField || [];
if (Array.isArray(customFields)) {
  const lvField = customFields.find(f =>
    f.key === 'lifetime_value' || f.id === 'lifetime_value'
  );
  if (lvField) {
    existingLifetime = parseFloat(lvField.value || lvField.field_value || 0);
  }
}

const newLifetime = existingLifetime + saleData.saleTotal;
const tags = [...saleData.tags];
if (newLifetime >= 500) tags.push('[system] vip');

return [{
  json: {
    ghl_contact_id: matcherData.ghl_contact_id,
    saleTotal: saleData.saleTotal,
    saleDate: saleData.saleDate,
    saleId: saleData.saleId,
    employeeId: saleData.employeeId,
    newLifetime,
    tags
  }
}];
